from typing import List, Union
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
from pydantic import BaseModel, validator, ValidationError


class InvoiceLine(BaseModel):
    sku: str
    quantity: int
    unit_price: Union[str, int, float, Decimal]

    @validator('quantity')
    def quantity_must_be_at_least_1(cls, v):
        if v < 1:
            raise ValueError('quantity must be at least 1')
        return v

    @validator('unit_price', pre=True)
    def unit_price_to_decimal(cls, v):
        try:
            d = Decimal(str(v))
        except Exception:
            raise ValueError('unit_price must be a number or numeric string')
        if d < 0:
            raise ValueError('unit_price must be >= 0')
        return d.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)


class Invoice(BaseModel):
    number: str
    issued_at: Union[str, datetime]
    lines: List[InvoiceLine]

    @validator('issued_at', pre=True)
    def parse_issued_at(cls, v):
        if isinstance(v, datetime):
            dt = v
        else:
            try:
                dt = datetime.fromisoformat(v)
            except Exception:
                raise ValueError('issued_at must be ISO 8601 datetime string or datetime object')
        if dt.tzinfo is None:
            # naive datetime, treat as UTC
            dt = dt.replace(tzinfo=timezone.utc)
        else:
            # convert to UTC
            dt = dt.astimezone(timezone.utc)
        return dt

    def json_dict(self):
        # Format issued_at as "YYYY-MM-DDTHH:MM:SSZ"
        issued_at_str = self.issued_at.strftime('%Y-%m-%dT%H:%M:%SZ')

        lines_out = []
        total = Decimal('0.00')
        for line in self.lines:
            unit_price_str = f"{line.unit_price:.2f}"
            line_total = line.unit_price * line.quantity
            total += line_total
            lines_out.append({
                'sku': line.sku,
                'quantity': line.quantity,
                'unit_price': unit_price_str,
            })

        total_str = f"{total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP):.2f}"

        return {
            'number': self.number,
            'issued_at': issued_at_str,
            'lines': lines_out,
            'total': total_str,
        }


def export_invoice(data: dict) -> str:
    try:
        invoice = Invoice.parse_obj(data)
    except ValidationError as e:
        # pydantic ValidationError inherits from ValueError
        raise ValueError(e)

    import json
    return json.dumps(invoice.json_dict(), separators=(',', ':'))

from typing import Optional, List, Dict, Any
from pydantic import BaseModel, validator, ValidationError


class ProfileModel(BaseModel):
    user_id: int
    display_name: str
    bio: Optional[str] = None
    zip_code: str

    @validator('user_id', pre=True)
    def user_id_must_be_int(cls, v: Any) -> int:
        # Accept numeric strings and ints, convert to int
        if isinstance(v, int):
            return v
        if isinstance(v, str) and v.isdigit():
            return int(v)
        raise ValueError('user_id must be an integer or numeric string')

    @validator('display_name', pre=True)
    def collapse_whitespace_and_validate(cls, v: Any) -> str:
        if not isinstance(v, str):
            raise ValueError('display_name must be a string')
        # Collapse internal whitespace to single spaces
        collapsed = ' '.join(v.split())
        if not collapsed:
            raise ValueError('display_name cannot be blank')
        return collapsed

    @validator('zip_code', pre=True)
    def zip_code_to_str(cls, v: Any) -> str:
        if isinstance(v, int):
            return str(v)
        if isinstance(v, str):
            return v
        raise ValueError('zip_code must be a string or integer')


def import_profiles(rows: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    valid_profiles = []
    for row in rows:
        try:
            profile = ProfileModel(**row)
            valid_profiles.append(profile.dict())
        except ValidationError:
            # silently skip invalid rows
            continue
    return valid_profiles

from typing import List
from pydantic import BaseModel, ValidationError


class CustomerModel(BaseModel):
    id: int
    name: str
    email: str


class ItemModel(BaseModel):
    sku: str
    quantity: int


class OrderModel(BaseModel):
    id: int
    customer: CustomerModel
    items: List[ItemModel]


def orders_payload(orders: list) -> list:
    result = []
    for order in orders:
        try:
            order_model = OrderModel(
                id=getattr(order, "id"),
                customer=CustomerModel(
                    id=getattr(order.customer, "id"),
                    name=getattr(order.customer, "name"),
                    email=getattr(order.customer, "email"),
                ),
                items=[
                    ItemModel(
                        sku=getattr(item, "sku"),
                        quantity=getattr(item, "quantity"),
                    )
                    for item in getattr(order, "items")
                ],
            )
            result.append(order_model.dict())
        except (AttributeError, ValidationError) as e:
            # Raise ValueError for missing or invalid attributes as requested
            raise ValueError(str(e)) from e
    return result

import re
from pydantic import BaseModel, validator, ValidationError, root_validator


class SignupModel(BaseModel):
    username: str
    email: str
    phone: str
    password: str
    password_confirm: str

    @validator("username")
    def username_valid(cls, v: str) -> str:
        if not re.fullmatch(r"^[a-z0-9_]{3,20}$", v):
            raise ValueError("username must match ^[a-z0-9_]{3,20}$")
        return v

    @validator("email")
    def email_valid(cls, v: str) -> str:
        v_strip = v.strip().lower()
        if "@" not in v_strip:
            raise ValueError("email must contain '@'")
        return v_strip

    @validator("phone")
    def phone_valid(cls, v: str) -> str:
        # Remove spaces, dots, dashes, parentheses
        compact = re.sub(r"[ .\-\(\)]", "", v)
        if not re.fullmatch(r"\+[0-9]{8,15}", compact):
            raise ValueError("phone must be '+' followed by 8-15 digits after removing spaces/dots/dashes/parentheses")
        return compact

    @validator("password")
    def password_length(cls, v: str) -> str:
        if len(v) < 8:
            raise ValueError("password must be at least 8 characters")
        return v

    @root_validator
    def passwords_match(cls, values):
        pw = values.get("password")
        pwc = values.get("password_confirm")
        if pw is None or pwc is None:
            raise ValueError("password and password_confirm must be provided")
        if pw != pwc:
            raise ValueError("password_confirm must equal password")
        return values


def validate_signup(data: dict) -> dict:
    validated = SignupModel(**data)
    return {
        "username": validated.username,
        "email": validated.email,
        "phone": validated.phone,
    }

from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
from typing import List, Union
from pydantic import BaseModel, Field, ValidationError, model_validator


class InvoiceLine(BaseModel):
    sku: str
    quantity: int = Field(..., ge=1)
    unit_price: Decimal = Field(..., ge=0)

    @model_validator(mode='before')
    @classmethod
    def parse_unit_price(cls, values):
        # Coerce unit_price from str/int/float to Decimal before validation
        up = values.get('unit_price')
        if up is None:
            return values
        try:
            values['unit_price'] = Decimal(str(up))
        except Exception as e:
            raise ValueError(f"unit_price must be a decimal convertible value: {e}") from e
        return values


class Invoice(BaseModel):
    number: str
    issued_at: Union[datetime, str]
    lines: List[InvoiceLine]

    model_config = {
        'from_attributes': True,
    }

    @model_validator(mode='before')
    @classmethod
    def parse_issued_at(cls, values):
        dt = values.get('issued_at')
        if dt is None:
            return values
        if isinstance(dt, str):
            try:
                # Parse ISO 8601 string
                # datetime.fromisoformat does not parse 'Z', so replace Z with +00:00
                s = dt
                if s.endswith('Z'):
                    s = s[:-1] + '+00:00'
                dt_parsed = datetime.fromisoformat(s)
            except Exception as e:
                raise ValueError(f"issued_at must be a valid ISO 8601 datetime string: {e}") from e
            values['issued_at'] = dt_parsed
        elif not isinstance(dt, datetime):
            raise ValueError("issued_at must be a datetime or ISO 8601 string")
        return values

    @model_validator(mode='after')
    def normalize_issued_at(self):
        dt = self.issued_at
        if dt.tzinfo is None:
            # naive datetime, treat as UTC
            dt = dt.replace(tzinfo=timezone.utc)
        else:
            # convert to UTC
            dt = dt.astimezone(timezone.utc)
        object.__setattr__(self, 'issued_at', dt)
        return self

    def total(self) -> Decimal:
        total = Decimal('0')
        for line in self.lines:
            total += line.unit_price * line.quantity
        return total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)


def export_invoice(data: dict) -> str:
    try:
        invoice = Invoice.model_validate(data)
    except ValidationError as e:
        raise ValueError(str(e)) from e

    # Prepare output dict
    issued_at_str = invoice.issued_at.strftime('%Y-%m-%dT%H:%M:%SZ')

    def format_price(d: Decimal) -> str:
        return f"{d.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP):.2f}"

    lines_out = []
    for line in invoice.lines:
        lines_out.append({
            'sku': line.sku,
            'quantity': line.quantity,
            'unit_price': format_price(line.unit_price),
        })

    total_str = format_price(invoice.total())

    import json
    out = {
        'number': invoice.number,
        'issued_at': issued_at_str,
        'lines': lines_out,
        'total': total_str,
    }
    return json.dumps(out, separators=(',', ':'))

from typing import Any, Optional
from pydantic import BaseModel, Field, ValidationError, field_validator


class Profile(BaseModel):
    user_id: int
    display_name: str
    bio: Optional[str] = None
    zip_code: str

    model_config = {
        "from_attributes": True,
    }

    @field_validator("display_name")
    @classmethod
    def collapse_whitespace(cls, v: str) -> str:
        # Collapse internal whitespace to single spaces and strip ends
        collapsed = " ".join(v.split())
        if not collapsed:
            raise ValueError("display_name cannot be blank")
        return collapsed

    @field_validator("zip_code", mode="before")
    @classmethod
    def coerce_zip_code_to_str(cls, v: Any) -> str:
        # Accept int or str, convert to str
        if isinstance(v, int):
            return str(v)
        if isinstance(v, str):
            return v
        raise TypeError("zip_code must be str or int")


def import_profiles(rows: list) -> list:
    valid_profiles = []
    for row in rows:
        try:
            profile = Profile.model_validate(row)
        except ValidationError:
            continue
        valid_profiles.append(profile.model_dump())
    return valid_profiles

